-- FR-STATE-01..10, FR-ACC-04, I-5..8, I-11..12: tenant-scoped immutable ledgers.
begin;
create extension if not exists pgcrypto;
do $$ declare r text; begin
  foreach r in array array['founder_role','lead_role','specialist_role','policy_role','ingress_role','voice_role'] loop
    if not exists(select from pg_roles where rolname=r) then execute format('create role %I nologin noinherit nobypassrls',r); end if;
  end loop;
end $$;
create schema if not exists private;
revoke all on schema private from public;
revoke create on schema public from public;
create function private.actor_id() returns uuid language sql stable set search_path='' as $$
  select (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid
$$;
create function private.caller_role() returns text language sql stable set search_path='' as $$
  select coalesce(nullif(current_setting('role',true),'none'),session_user::text)
$$;
create function private.require_role(allowed text[]) returns void language plpgsql set search_path='' as $$
begin if not(private.caller_role()=any(allowed)) then raise exception 'invariant_violation: role denied' using errcode='42501'; end if; end $$;

create table public.founders(id uuid primary key default gen_random_uuid(),auth_user_id uuid not null unique,profile jsonb not null default '{}',involvement_dial text not null default 'do' check(involvement_dial in('guide','do','help')),locale text not null default 'en',created_at timestamptz not null default now());
create table public.missions(id uuid primary key default gen_random_uuid(),founder_id uuid not null references public.founders(id),type text not null check(type in('discover','launch')),goal_brief text not null,currency text not null check(currency~'^[A-Z]{3}$'),sandbox_mode boolean not null default true,involvement text not null default 'do' check(involvement in('guide','do','help')),created_at timestamptz not null default now(),unique(id,founder_id));
create table public.mission_transitions(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),status text not null check(status in('active','paused','ended')),terminal_decision_id uuid,closing_record_version_id uuid,actor_id uuid not null,created_at timestamptz not null default now(),check(status<>'ended' or(terminal_decision_id is not null and closing_record_version_id is not null)));
create function private.owns_founder(p_founder uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select from public.founders f where f.id=p_founder and f.auth_user_id=private.actor_id())$$;
create function private.owns_mission(p_mission uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select from public.missions m where m.id=p_mission and private.owns_founder(m.founder_id)) and (private.caller_role() in('founder_role','authenticated') or (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'mission_id')=p_mission::text)$$;
create function private.assert_mission(p_mission uuid) returns void language plpgsql stable set search_path='' as $$begin if not private.owns_mission(p_mission) then raise exception 'invariant_violation: mission denied' using errcode='42501';end if;end$$;
create table public.state_nodes(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),kind text not null check(kind in('decision','artifact','version','evidence','commitment')),unique(mission_id,id));
create table public.decisions(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),kind text not null check(kind in('goal','constraint','selection','mandate','engagement','change','terminal')),outcome text check(outcome in('brand','product','supply','commerce','compliance','demand')),gate text,packet jsonb not null,approved_version_refs uuid[] not null default '{}',evidence_refs uuid[] not null default '{}',supersedes_id uuid,actor_id uuid not null,created_at timestamptz not null default now(),unique(mission_id,id),foreign key(mission_id,id) references public.state_nodes(mission_id,id),foreign key(mission_id,supersedes_id) references public.decisions(mission_id,id),check(supersedes_id is null or supersedes_id<>id));
create table public.decision_resolutions(id uuid primary key default gen_random_uuid(),mission_id uuid not null,decision_id uuid not null,response text not null check(response in('approve','choose','reject','defer','question')),option_id text,actor_id uuid not null,created_at timestamptz not null default now(),foreign key(mission_id,decision_id) references public.decisions(mission_id,id));
create unique index decision_one_binding_resolution on public.decision_resolutions(decision_id) where response in('approve','choose','reject');
create table public.decision_supersessions(id uuid primary key default gen_random_uuid(),mission_id uuid not null,previous_id uuid not null unique,replacement_id uuid not null unique,created_at timestamptz not null default now(),foreign key(mission_id,previous_id) references public.decisions(mission_id,id),foreign key(mission_id,replacement_id) references public.decisions(mission_id,id),check(previous_id<>replacement_id));
create table public.dependencies(id uuid primary key default gen_random_uuid(),mission_id uuid not null,upstream_id uuid not null,dependent_id uuid not null,reason text not null,created_at timestamptz not null default now(),foreign key(mission_id,upstream_id) references public.state_nodes(mission_id,id),foreign key(mission_id,dependent_id) references public.state_nodes(mission_id,id),unique(mission_id,upstream_id,dependent_id),check(upstream_id<>dependent_id));
create table public.stale_marks(id uuid primary key default gen_random_uuid(),mission_id uuid not null,node_id uuid not null,cause_id uuid not null,created_at timestamptz not null default now(),foreign key(mission_id,node_id) references public.state_nodes(mission_id,id),foreign key(mission_id,cause_id) references public.state_nodes(mission_id,id),unique(mission_id,node_id,cause_id));
create table public.artifacts(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),type text not null,outcome text not null check(outcome in('brand','product','supply','commerce','compliance','demand')),title text not null,actor_id uuid not null,created_at timestamptz not null default now(),unique(mission_id,id),foreign key(mission_id,id) references public.state_nodes(mission_id,id));
create table public.runs(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),role text not null,brief jsonb not null,context_pack_hash text not null,model_tier text not null,status text not null default 'scheduled',tokens integer not null default 0 check(tokens>=0),cost_minor bigint not null default 0 check(cost_minor>=0),result jsonb,created_at timestamptz not null default now(),unique(mission_id,id));
create table public.artifact_versions(id uuid primary key default gen_random_uuid(),mission_id uuid not null,artifact_id uuid not null,version_no integer not null check(version_no>0),content jsonb not null,file_refs text[] not null default '{}',variation_request text,created_by_run_id uuid,created_at timestamptz not null default now(),unique(mission_id,id),unique(artifact_id,version_no),foreign key(mission_id,id) references public.state_nodes(mission_id,id),foreign key(mission_id,artifact_id) references public.artifacts(mission_id,id),foreign key(mission_id,created_by_run_id) references public.runs(mission_id,id));
create table public.artifact_statuses(id uuid primary key default gen_random_uuid(),mission_id uuid not null,artifact_version_id uuid not null,status text not null check(status in('draft','proposed','approved','rejected','superseded','stale')),decision_id uuid,actor_id uuid not null,created_at timestamptz not null default now(),foreign key(mission_id,artifact_version_id) references public.artifact_versions(mission_id,id),foreign key(mission_id,decision_id) references public.decisions(mission_id,id));
create table public.counterparties(id uuid primary key default gen_random_uuid(),founder_id uuid not null references public.founders(id),kind text not null check(kind in('supplier','specialist','service')),name text not null,channels jsonb not null default '{}',verification jsonb not null default '{}',opt_out boolean not null default false,locale text not null default 'en',created_at timestamptz not null default now(),unique(founder_id,id));
create table public.founder_accounts(id uuid primary key default gen_random_uuid(),founder_id uuid not null references public.founders(id),provider text not null,status text not null check(status in('connected','revoked')),scopes text[] not null,created_at timestamptz not null default now(),unique(founder_id,id));
-- Secret references are deliberately outside the exposed public schema.
create table private.account_secrets(account_id uuid primary key references public.founder_accounts(id),secret_ref text not null);
create table public.account_revocations(id uuid primary key default gen_random_uuid(),founder_id uuid not null,account_id uuid not null,created_at timestamptz not null default now(),foreign key(founder_id,account_id) references public.founder_accounts(founder_id,id),unique(account_id));
create table public.mandates(id uuid primary key default gen_random_uuid(),mission_id uuid not null,decision_id uuid not null,type text not null,scope jsonb not null,ceiling_per bigint not null check(ceiling_per>=0),ceiling_total bigint not null check(ceiling_total>=0),currency text not null check(currency~'^[A-Z]{3}$'),expires_at timestamptz not null,created_at timestamptz not null default now(),unique(mission_id,id),foreign key(mission_id,decision_id) references public.decisions(mission_id,id));
create table public.mandate_revocations(id uuid primary key default gen_random_uuid(),mission_id uuid not null,mandate_id uuid not null unique,created_at timestamptz not null default now(),foreign key(mission_id,mandate_id) references public.mandates(mission_id,id));
create table public.approvals(id uuid primary key default gen_random_uuid(),mission_id uuid not null,decision_id uuid not null,binding jsonb not null,token_hash text not null unique check(token_hash~'^[0-9a-f]{64}$'),expires_at timestamptz not null,created_at timestamptz not null default now(),unique(mission_id,id),foreign key(mission_id,decision_id) references public.decisions(mission_id,id));
create table public.approval_invalidations(id uuid primary key default gen_random_uuid(),mission_id uuid not null,approval_id uuid not null unique,reason text not null,created_at timestamptz not null default now(),foreign key(mission_id,approval_id) references public.approvals(mission_id,id));
create table public.effect_authorizations(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),intent jsonb not null,intent_hash text not null,idempotency_key text not null,mandate_id uuid,approval_id uuid,amount_minor bigint not null default 0 check(amount_minor>=0),sandbox_mode boolean not null,created_at timestamptz not null default now(),unique(mission_id,id),unique(mission_id,idempotency_key),foreign key(mission_id,mandate_id) references public.mandates(mission_id,id),foreign key(mission_id,approval_id) references public.approvals(mission_id,id),check(mandate_id is not null or approval_id is not null));
create table public.approval_consumptions(id uuid primary key default gen_random_uuid(),mission_id uuid not null,approval_id uuid not null unique,authorization_id uuid not null unique,created_at timestamptz not null default now(),foreign key(mission_id,approval_id) references public.approvals(mission_id,id),foreign key(mission_id,authorization_id) references public.effect_authorizations(mission_id,id));
create table public.provider_receipts(id uuid primary key default gen_random_uuid(),mission_id uuid not null,authorization_id uuid not null unique,provider text not null,provider_reference text not null,operation text not null,sandbox_mode boolean not null,data jsonb not null,created_at timestamptz not null default now(),unique(mission_id,id),unique(provider,provider_reference,operation,sandbox_mode),foreign key(mission_id,authorization_id) references public.effect_authorizations(mission_id,id));
create table public.effect_states(id uuid primary key default gen_random_uuid(),mission_id uuid not null,authorization_id uuid not null,status text not null check(status in('reserved','started','performed','failed','ambiguous')),receipt_id uuid,reason text,created_at timestamptz not null default now(),foreign key(mission_id,authorization_id) references public.effect_authorizations(mission_id,id),foreign key(mission_id,receipt_id) references public.provider_receipts(mission_id,id),check(status<>'performed' or receipt_id is not null));
create table public.evidence(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),outcome text check(outcome in('brand','product','supply','commerce','compliance','demand')),kind text not null,trust text not null check(trust in('planned','performed','claimed','verified','founder_confirmed')),payload jsonb not null,source_type text not null check(source_type in('url','message','receipt','founder','document','event','poll')),source_reference text not null,provider_receipt_id uuid,supersedes_id uuid,sandbox_mode boolean not null,actor_id uuid not null,created_at timestamptz not null default now(),unique(mission_id,id),foreign key(mission_id,id) references public.state_nodes(mission_id,id),foreign key(mission_id,provider_receipt_id) references public.provider_receipts(mission_id,id),foreign key(mission_id,supersedes_id) references public.evidence(mission_id,id),check(trust<>'performed' or provider_receipt_id is not null));
create table public.commitments(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),party_id uuid,direction text not null check(direction in('inbound','outbound')),description text not null,due_at timestamptz not null,escalation_step integer not null default 0,actor_id uuid not null,created_at timestamptz not null default now(),unique(mission_id,id),foreign key(mission_id,id) references public.state_nodes(mission_id,id));
create table public.commitment_states(id uuid primary key default gen_random_uuid(),mission_id uuid not null,commitment_id uuid not null,status text not null check(status in('open','overdue','closed','cancelled')),closed_by_evidence_id uuid,created_at timestamptz not null default now(),foreign key(mission_id,commitment_id) references public.commitments(mission_id,id),foreign key(mission_id,closed_by_evidence_id) references public.evidence(mission_id,id),check(status<>'closed' or closed_by_evidence_id is not null));
create table public.events(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),type text not null,payload jsonb not null,provider text,provider_event_id text,signature_verified boolean not null default false,received_at timestamptz not null default now(),unique(mission_id,id),unique(provider,provider_event_id),check(provider is null or(signature_verified and provider_event_id is not null)));
create table public.event_consumptions(id uuid primary key default gen_random_uuid(),mission_id uuid not null,event_id uuid not null,consumer text not null,created_at timestamptz not null default now(),foreign key(mission_id,event_id) references public.events(mission_id,id),unique(event_id,consumer));
create table public.outbox(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),type text not null,payload jsonb not null,created_at timestamptz not null default now());
create table public.outbox_deliveries(id uuid primary key default gen_random_uuid(),mission_id uuid not null,outbox_id uuid not null references public.outbox(id),created_at timestamptz not null default now(),unique(outbox_id));
create table public.payments(id uuid primary key default gen_random_uuid(),mission_id uuid not null,authorization_id uuid not null unique,provider text not null,payee_id uuid not null,instrument_id uuid not null,amount_minor bigint not null check(amount_minor>0),currency text not null check(currency~'^[A-Z]{3}$'),purpose text not null,artifact_version_id uuid not null,sandbox_mode boolean not null,created_at timestamptz not null default now(),unique(mission_id,id),foreign key(mission_id,authorization_id) references public.effect_authorizations(mission_id,id),foreign key(mission_id,artifact_version_id) references public.artifact_versions(mission_id,id));
create table public.payment_states(id uuid primary key default gen_random_uuid(),mission_id uuid not null,payment_id uuid not null,state text not null check(state in('planned','approved','executing','captured','failed','refunded')),receipt_id uuid,confirmation_event_id uuid,created_at timestamptz not null default now(),foreign key(mission_id,payment_id) references public.payments(mission_id,id),foreign key(mission_id,receipt_id) references public.provider_receipts(mission_id,id),foreign key(mission_id,confirmation_event_id) references public.events(mission_id,id),check(state not in('captured','refunded') or(receipt_id is not null and confirmation_event_id is not null)));
create table public.money_ledger(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),kind text not null check(kind in('envelope','forecast','committed','spent','refund')),amount_minor bigint not null check(amount_minor>=0),currency text not null check(currency~'^[A-Z]{3}$'),basis text not null check(basis in('estimate','claimed','accepted')),envelope text not null,ref_id uuid,receipt_id uuid,confirmation_event_id uuid,sandbox_mode boolean not null,fx_rate numeric,fx_source text,fx_at timestamptz,created_at timestamptz not null default now(),foreign key(mission_id,receipt_id) references public.provider_receipts(mission_id,id),foreign key(mission_id,confirmation_event_id) references public.events(mission_id,id),check(kind not in('spent','refund') or(receipt_id is not null and confirmation_event_id is not null)),check(fx_rate is null or(fx_source is not null and fx_at is not null and fx_rate>0)));
create unique index money_receipt_once on public.money_ledger(receipt_id,kind) where receipt_id is not null;
create table public.activity(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),run_id uuid,step_id text,label text not null check(label in('planned','performed','claimed','verified','proposed','approved','blocked','failed','corrected')),summary text not null,refs uuid[] not null default '{}',receipt_id uuid,actor_id uuid not null,created_at timestamptz not null default now(),foreign key(mission_id,run_id) references public.runs(mission_id,id),foreign key(mission_id,receipt_id) references public.provider_receipts(mission_id,id),check(label<>'performed' or receipt_id is not null));
create table public.threads(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),counterparty_id uuid,created_at timestamptz not null default now(),unique(mission_id,id));
create table public.messages(id uuid primary key default gen_random_uuid(),mission_id uuid not null,thread_id uuid not null,channel text not null,direction text not null check(direction in('inbound','outbound','founder','lead')),original text not null,translation text,provider_id text,mandate_id uuid,receipt_id uuid,window_state jsonb not null default '{}',artifact_version_refs uuid[] not null default '{}',created_at timestamptz not null default now(),foreign key(mission_id,thread_id) references public.threads(mission_id,id),foreign key(mission_id,mandate_id) references public.mandates(mission_id,id),foreign key(mission_id,receipt_id) references public.provider_receipts(mission_id,id),check(direction<>'outbound' or receipt_id is not null));
create table public.tasks(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),run_id uuid,objective text not null,status text not null,deadline timestamptz,created_at timestamptz not null default now(),foreign key(mission_id,run_id) references public.runs(mission_id,id));
create table public.focus_events(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),node_id uuid,actor_id uuid not null,created_at timestamptz not null default now(),foreign key(mission_id,node_id) references public.state_nodes(mission_id,id));
create table public.blockers(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),outcome text not null,blocking_outcome text not null,required_level integer not null check(required_level between 1 and 5),description text not null,node_id uuid,created_at timestamptz not null default now(),foreign key(mission_id,node_id) references public.state_nodes(mission_id,id));
create table public.readiness_rules(id text primary key,version integer not null,outcome text not null,level integer not null check(level between 1 and 5),evidence_kinds text[] not null,decision_gates text[] not null,high_trust boolean not null,review_status text not null check(review_status='reviewed'),unique(version,outcome,level));
create table public.category_profiles(id text not null,version integer not null,content jsonb not null,review_status text not null check(review_status in('unverified','reviewed')),sources text[] not null,primary key(id,version));
create table public.playbooks(id text not null,version integer not null,content jsonb not null,review_status text not null,sources text[] not null,primary key(id,version));
create table public.templates(id text not null,version integer not null,content jsonb not null,review_status text not null,sources text[] not null,primary key(id,version));
create table private.platform_controls(singleton boolean primary key default true check(singleton),effects_enabled boolean not null default false);
insert into private.platform_controls values(true,false);

-- RLS applies to runtime roles as well as founders. No application role bypasses it.
do $$declare t record;begin
  for t in select tablename from pg_tables where schemaname='public' and tablename not in('readiness_rules','category_profiles','playbooks','templates') loop
    execute format('alter table public.%I enable row level security',t.tablename);
    execute format('alter table public.%I force row level security',t.tablename);
    if t.tablename='founders' then execute format('create policy tenant_scope on public.%I using(auth_user_id=private.actor_id()) with check(auth_user_id=private.actor_id())',t.tablename);
    elsif t.tablename in('counterparties','founder_accounts','account_revocations','missions') then execute format('create policy tenant_scope on public.%I using(private.owns_founder(founder_id)) with check(private.owns_founder(founder_id))',t.tablename);
    else execute format('create policy tenant_scope on public.%I using(private.owns_mission(mission_id)) with check(private.owns_mission(mission_id))',t.tablename);end if;
    execute format('grant select on public.%I to founder_role,lead_role,specialist_role,policy_role,ingress_role,voice_role',t.tablename);
  end loop;
end$$;
grant usage on schema public,private to founder_role,lead_role,specialist_role,policy_role,ingress_role,voice_role;
grant execute on function private.actor_id(),private.caller_role(),private.owns_founder(uuid),private.owns_mission(uuid),private.assert_mission(uuid),private.require_role(text[]) to founder_role,lead_role,specialist_role,policy_role,ingress_role,voice_role;
grant select on public.readiness_rules,public.category_profiles,public.playbooks,public.templates to founder_role,lead_role,specialist_role,policy_role,ingress_role,voice_role;
grant insert on public.founders,public.missions to founder_role;
grant insert on public.runs,public.tasks,public.focus_events,public.activity,public.outbox,public.event_consumptions,public.outbox_deliveries,public.blockers to lead_role;
grant insert on public.runs,public.activity,public.focus_events to specialist_role;
grant insert on public.events to ingress_role;
grant insert on public.counterparties,public.threads,public.messages to specialist_role;
grant insert on public.messages,public.threads,public.focus_events to founder_role;
-- Functions are opt-in; public must never inherit SECURITY DEFINER execution.
revoke execute on all functions in schema private from public;
create function private.immutable_row() returns trigger language plpgsql set search_path='' as $$begin raise exception 'invariant_violation: append-only ledger' using errcode='42501';end$$;
do $$declare t record;begin for t in select tablename from pg_tables where schemaname='public' loop execute format('create trigger immutable_row before update or delete on public.%I for each row execute function private.immutable_row()',t.tablename);end loop;end$$;
commit;
